/* ---------- confiance donn\u00e9es (Rulebook P7) ---------- */
function v5conf(){
  var q=DB.in||{}, R=moteur(), checks=[], sc=0, tot=0;
  function add(w,ok,miss){ tot+=w; if(ok)sc+=w; else checks.push(miss); }
  add(15, q.panier>0, 'Panier moyen manquant');
  add(15, q.cmdj>0, 'Commandes / jour manquantes');
  add(15, (q.nour||0)>0, 'Achats nourriture manquants');
  add(15, ((q.dirb||0)+(q.salb||0))>0, 'Aucun salaire saisi');
  add(10, (function(){var f=0;for(var i=1;i<=10;i++)f+=(q['f'+i]||0);return f>0;})(), 'Aucune charge fixe saisie');
  add(5, q.jsem>=1&&q.jsem<=7, 'Jours/semaine incoh\u00e9rents');
  add(5, q.tva>=0&&q.tva<=30, 'TVA incoh\u00e9rente');
  add(5, q.obj>0, 'Objectif mensuel non fix\u00e9');
  if(R.ready){
    add(10, R.v.fc>=10&&R.v.fc<=55, 'Food cost hors plage plausible (10\u201355 %)');
    add(5, R.v.rn<=35, 'Marge > 35 % \u2014 v\u00e9rifier la saisie');
  } else { tot+=15; }
  return { pct: tot>0?Math.round(sc/tot*100):0, miss: checks };
}
/* ---------- moteur de recommandations (Rulebook P4-P5) ---------- */
function impScore(e){ return e>15000?95:(e>10000?80:(e>5000?60:(e>1000?30:15))); }
function v5recos(){
  syncFB();
  var R=moteur(); if(!R.ready) return {ready:false};
  var C=v5conf(), d=R.d, v=R.v, s=R.s, ca=d.ca, list=[];
  var confBase = C.pct<60 ? 65 : 85;
  if(C.pct<50){
    return {ready:true, blocked:true, conf:C};
  }
  /* rang 2 — critiques */
  if(v.rn<0){
    list.push({id:'perte',rank:2,t:'Structure en perte \u2014 le mod\u00e8le ne se paie pas',
      p:'R\u00e9sultat avant imp\u00f4t '+eur(Math.round(d.res))+'/an. Chaque euro de CA suppl\u00e9mentaire ne suffira pas : c\u2019est la structure (charges variables, masse salariale, panier) qu\u2019il faut recalibrer.',
      why:'Rentabilit\u00e9 n\u00e9gative = rang critique \u2014 le score est plafonn\u00e9 tant que la perte dure.',
      urg:95, imp:Math.abs(Math.round(d.res)), fac:30, conf:confBase});
  }
  var msC=(typeof repereMS==='function'?repereMS().sec:36), msH=(typeof repereMS==='function'&&repereMS().haut)||msC+6;/* C309 (décision 5) : conseill\u00e9 du type d\u2019\u00e9tablissement, trop lourd au-del\u00e0 de son rep\u00e8re haut (comme l\u2019Indice) */
  if(v.ms>msH){
    var gMS=Math.round((v.ms-msH)/100*ca);
    list.push({id:'ms',rank:2,t:'Masse salariale critique : '+pc(v.ms,0)+' du CA',
      p:'Au-dessus de '+msH+' % des ventes : trop lourd. Revenir \u00e0 ce seuil repr\u00e9sente \u2248 '+eur(gMS)+'/an. '+srvT('leviersMs'),
      why:'Plus de '+msH+' % des ventes (rep\u00e8re haut de votre type d\u2019\u00e9tablissement ; conseill\u00e9 : '+msC+' %) = trop lourd \u2014 ce n\u2019est pas une moyenne sectorielle officielle.',
      urg:80, imp:gMS, fac:30, conf:confBase});
  } else if(v.ms>msC){
    var gMS2=Math.round((v.ms-msC)/100*ca);
    list.push({id:'ms2',rank:4,t:'Masse salariale en vigilance : '+pc(v.ms,0)+' du CA',
      p:'Au-dessus des '+msC+' % conseill\u00e9s pour votre type d\u2019\u00e9tablissement, sous les '+msH+' % (trop lourd). Ramener vers '+msC+' % repr\u00e9sente \u2248 '+eur(gMS2)+'/an \u2014 avant toute action, v\u00e9rifiez planning, heures et organisation.',
      why:'Entre '+msC+' et '+msH+' % des ventes = \u00e0 surveiller, comme la jauge de l\u2019\u00e9quipe \u2014 pas une norme sectorielle.',
      urg:40, imp:gMS2, fac:35, conf:confBase});
  }
  if(v.fc>40){
    var gFC=Math.round((v.fc-35)/100*ca);
    list.push({id:'fc',rank:2,t:'Food cost critique : '+pc(v.fc,0)+' du CA',
      p:'Bien au-dessus de la zone de travail interne Verdict. Revenir vers le rep\u00e8re 35 % repr\u00e9sente \u2248 '+eur(gFC)+'/an. Avant de conclure : v\u00e9rifiez stock, fiches techniques, portions, pertes et classement comptable.',
      why:'Food cost > 40 % = rang critique dans la grille Verdict \u2014 le seuil n\u2019est pas pr\u00e9sent\u00e9 comme une moyenne FIBEN.',
      urg:78, imp:gFC, fac:45, conf:confBase});
  } else if(v.fc>35){
    var gFC2=Math.round((v.fc-35)/100*ca);
    list.push({id:'fc2',rank:4,t:'Food cost \u00e9lev\u00e9 : '+pc(v.fc,0)+' du CA',
      p:'Au-dessus du rep\u00e8re de pilotage Verdict. Revenir vers 35 % repr\u00e9sente \u2248 '+eur(gFC2)+'/an \u2014 \u00e0 confirmer avec stock, fiches, portions, pertes et factures.',
      why:'Au-dessus du rep\u00e8re interne mais sous le seuil critique de la grille Verdict.',
      urg:48, imp:gFC2, fac:45, conf:confBase});
  }
  /* rang 3 — r\u00e9silience */
  if(s.sen<50 && v.rn>=0){
    var gP=Math.round(1.5/(1+d.tva)*d.cmdAn*(d.ca>0?d.mc/d.ca:0));
    list.push({id:'sen',rank:3,t:'Renforcer la r\u00e9silience : le mod\u00e8le encaisse mal un choc',
      p:'Sensibilit\u00e9 not\u00e9e '+Math.round(s.sen)+'/100 : un recul de 10 % du CA ram\u00e8ne la marge \u00e0 '+pc(v.sen,1)+'. Levier n\u00b01 : le panier moyen \u2014 +1,50 \u20ac TTC par commande \u2248 '+eur(gP)+'/an de contribution, sans un couvert de plus.',
      why:'Votre note la plus basse en r\u00e9silience, et le panier est le levier le plus facile \u00e0 activer (suggestion, desserts, boissons).',
      urg:58+Math.round((50-s.sen)/2), imp:gP, fac:70, conf:confBase});
  }
  if(v.pm<999 && v.pm>85 && v.rn>=0){
    list.push({id:'pm',rank:3,t:'Point mort tardif : '+pc(v.pm,0)+' du CA',
      p:(d.jMois>0?'\u2248 '+Math.round(v.pm/100*d.jMois)+' jours d\u2019ouverture sur '+d.jMois+' pour couvrir les charges':'Il faut '+pc(v.pm,0)+' du mois pour couvrir les charges')+' \u2014 le r\u00e9sultat se joue sur la fin de mois. Chaque point de charges fixes gagn\u00e9 rapproche le seuil.',
      why:'Au-dessus de 85 %, la moindre semaine molle met le mois en danger.',
      urg:52, imp:Math.round(0.02*ca), fac:40, conf:confBase});
  }
  /* rang 4 — commissions */
  if(v.com>15){
    var gCom=Math.round((v.com-15)/100*ca);
    list.push({id:'com',rank:4,t:'Commissions plateformes : '+pc(v.com,0)+' du CA',
      p:'Poids des commissions \u00e9lev\u00e9 dans votre CA. L\u2019\u00e9cart au rep\u00e8re interne Verdict de 15 % repr\u00e9sente \u2248 '+eur(gCom)+'/an. V\u00e9rifiez d\u2019abord vos taux contractuels, le mix livraison/direct et la contribution nette par canal.',
      why:'Au-del\u00e0 du rep\u00e8re interne Verdict de 15 % du CA, le moteur demande une analyse du canal \u2014 ce n\u2019est pas une norme sectorielle.',
      urg:50, imp:gCom, fac:40, conf:confBase});
  }
  /* System — croisement */
  var st = DB.plats.length ? carteStats() : null;
  if(st && st.theoR>0){
    var pts=v.fc-st.theoNourR, eurAn=Math.round(pts/100*ca);
    if(pts>=4){
      var xz=xzone(Math.abs(pts));
      list.push({id:'x',rank:pts>=12?2:3,sys:true,t:'Expliquer l\u2019\u00e9cart food cost : '+fr(pts,1)+' pts \u00b7 '+eur(eurAn)+'/an',
        p:'Pour la nourriture, la carte dit '+pc(st.theoNourR,1)+', les comptes disent '+pc(v.fc,1)+'. Ordre d\u2019investigation : p\u00e9rim\u00e8tre (boissons, caf\u00e9, staff meal), puis portions et pertes. Aucune conclusion avant v\u00e9rification.',
        why:'\u00c9cart '+xz.t.toLowerCase()+' \u2014 l\u2019impact potentiel est fort mais l\u2019\u00e9cart doit d\u2019abord \u00eatre expliqu\u00e9.',
        urg:pts>=12?72:(pts>=8?62:45), imp:eurAn, fac:55, conf:confBase});
    }
  }
  /* rang 5 */
  if(!list.length){
    list.push({id:'ok',rank:5,t:'Rien d\u2019urgent \u2014 la structure tient',
      p:'Aucun seuil critique franchi. Les 12 indicateurs ne sont jamais tous verts : garde le rythme de saisie, le Pilote chaque matin, et r\u00e9examine au premier feu orange.',
      why:'Aucune alerte de rang 1\u20134 d\u00e9clench\u00e9e sur vos chiffres actuels.',
      urg:15, imp:0, fac:90, conf:confBase});
  }
  list.forEach(function(r){
    r.prio = Math.round(r.urg*.40 + impScore(r.imp)*.35 + r.fac*.15 + r.conf*.10);
    if(FB[r.id]==='no') r.veille=true;
  });
  list.sort(function(a,b){ return (a.veille?1:0)-(b.veille?1:0) || b.prio-a.prio; });
  return {ready:true, blocked:false, list:list.slice(0,5), conf:C};
}
/* V10.11 — l'ancien Conseil ne possède plus son propre moteur. Il traduit
   la décision du point 11 pour les anciens appels et pour Vera. */
var v5recosLegacy=v5recos;
v5recos=function(){
  syncFB();
  var D=DecisionEngine.PrioritiesEngine.decision(DB);
  if(!D.ready)return {ready:false};
  var src=D.items&&D.items.length?D.items:[{id:'ok',level:'opportunity',urgency:'month',diagnosis:p11t('noUrgent'),action:p11t('noUrgentText'),whyFirst:'Aucune alerte structurelle déclenchée.',impact:{annual:0},confidence:.9,rankScore:20}];
  var list=src.map(function(p){
    var k=p.impact&&p.impact.kind,annual=p.impact&&p.impact.annual||0;
    return {id:p.id,rank:p.level==='critical'?2:(p.level==='warning'?3:5),t:p.diagnosis,p:p.action,why:p.whyFirst||p.detail,
      urg:p11UrgencyScore(p.urgency),imp:(k==='scenario_gain'?annual:0),fac:{easy:90,medium:60,hard:35}[p.difficulty]||60,
      conf:Math.round((p.confidence||.8)*100),prio:p.rankScore||50,source:p};
  });
  list.forEach(function(r){if(FB[r.id]==='no')r.veille=true;});
  list.sort(function(a,b){return (a.veille?1:0)-(b.veille?1:0)||b.prio-a.prio;});
  return {ready:true,blocked:false,list:list,conf:{pct:Math.round(((D.top&&D.top.confidence)||.9)*100),miss:[]},source:'point11'};
};
window.v5recos=v5recos;
