function prevT(k,v){var i=['fr','en','es','it','de','nl','pt'].indexOf(typeof LOCALE!=='undefined'?LOCALE:'fr');if(i<0)i=0;var a=PREV_TX[k]||[k],s=a[i]||a[0];v=v||{};return String(s).replace(/\{(\w+)\}/g,function(_,x){return v[x]!=null?v[x]:'';});}
function prevVersionner(){var R=moteur();if(!R||!R.ready)return null;var S=piloteMoisEtat(R);if(!S||!S.projection||!S.projection.disponible||S.projection.ca==null)return null;
  var op=verdictOperationalClock(),jour=String(op.key).slice(0,10),mois=jour.slice(0,7),tva=Number(R.d.tva)||0;
  var v={at:new Date().toISOString(),jour:jour,ca:Math.round(S.projection.ca*100)/100,caHT:Math.round(S.projection.ca/(1+tva)*100)/100,resultat:S.projection.resultat!=null?Math.round(S.projection.resultat):null,
    niveau:S.confiance.niveau,raisons:(S.confiance.raisons||[]).slice(),saisis:S.donnees.saisis,cumul:Math.round(S.donnees.cumul*100)/100,joursRestants:S.rythme?S.rythme.jours:null,methode:'cumul+moyenne-meme-jour-semaine',statut:'projection'};
  DB.previsionsVersions=DB.previsionsVersions||{};var L=DB.previsionsVersions[mois]=DB.previsionsVersions[mois]||[],last=L[L.length-1],sig=function(x){return [x.ca,x.saisis,x.cumul,x.niveau].join('|');};
  if(last&&sig(last)===sig(v))return {etat:'same',version:last};v.version=L.length?(L[L.length-1].version||L.length)+1:1;L.push(v);if(L.length>62)L.splice(1,L.length-62);try{save();}catch(e){}return {etat:'new',version:v};}
