function sourcesVeriteHTML(){var h='<div class="card" id="sourcesVerite"><h3 style="margin:0 0 6px">'+aideEsc(svtT('titre'))+'</h3>';for(var n=1;n<=9;n++)h+='<p class="note svt-l" style="margin:3px 0">'+aideEsc(svtT('l'+n))+'</p>';return h+'</div>';}
