var VAL_TX={titre:['Ce que Verdict vous a déjà permis de comprendre','What Verdict has already helped you understand','Lo que Verdict ya le ha permitido comprender','Ciò che Verdict vi ha già permesso di capire','Was Verdict Ihnen schon verständlich gemacht hat','Wat Verdict u al heeft laten begrijpen','O que o Verdict já lhe permitiu compreender'],
 prob:['Problèmes détectés : {n} priorité(s) — {l}','Problems detected: {n} priority(ies) — {l}','Problemas detectados: {n} prioridad(es) — {l}','Problemi rilevati: {n} priorità — {l}','Erkannte Probleme: {n} Priorität(en) — {l}','Gedetecteerde problemen: {n} prioriteit(en) — {l}','Problemas detetados: {n} prioridade(s) — {l}'],
 dec:['Décisions : {d} décidée(s) ou en cours, {m} mesurée(s), {a} abandonnée(s)','Decisions: {d} decided or in progress, {m} measured, {a} dropped','Decisiones: {d} decidida(s) o en curso, {m} medida(s), {a} abandonada(s)','Decisioni: {d} decise o in corso, {m} misurate, {a} abbandonate','Entscheidungen: {d} beschlossen oder laufend, {m} gemessen, {a} aufgegeben','Beslissingen: {d} genomen of lopend, {m} gemeten, {a} stopgezet','Decisões: {d} decidida(s) ou em curso, {m} medida(s), {a} abandonada(s)'],
 evo:['Évolution suivie : {h} mois d’historique, {c} mois clos, {p} version(s) de prévision','Tracked evolution: {h} month(s) of history, {c} closed month(s), {p} forecast version(s)','Evolución seguida: {h} mes(es) de historial, {c} mes(es) cerrado(s), {p} versión(es) de previsión','Evoluzione seguita: {h} mese/i di storico, {c} mese/i chiuso/i, {p} versione/i di previsione','Verfolgte Entwicklung: {h} Monat(e) Verlauf, {c} abgeschlossene(r) Monat(e), {p} Prognoseversion(en)','Gevolgde evolutie: {h} maand(en) historiek, {c} afgesloten maand(en), {p} prognoseversie(s)','Evolução acompanhada: {h} mês(es) de histórico, {c} mês(es) fechado(s), {p} versão(ões) de previsão'],
 est:['Gains estimés des décisions en cours : {v} par an — une estimation, pas une preuve.','Estimated gains of ongoing decisions: {v} a year — an estimate, not proof.','Ganancias estimadas de las decisiones en curso: {v} al año — una estimación, no una prueba.','Guadagni stimati delle decisioni in corso: {v} all’anno — una stima, non una prova.','Geschätzte Gewinne laufender Entscheidungen: {v} pro Jahr — eine Schätzung, kein Beweis.','Geschatte winst van lopende beslissingen: {v} per jaar — een schatting, geen bewijs.','Ganhos estimados das decisões em curso: {v} por ano — uma estimativa, não uma prova.'],
 obs:['Résultats observés sur les décisions mesurées : {v} sur leurs périodes de mesure (constaté après les décisions, sans preuve qu’elles en soient la seule cause).','Observed results on measured decisions: {v} over their measurement periods — observed ≠ proven effect of the decision.','Resultados observados en las decisiones medidas: {v} en sus periodos de medición — observado ≠ efecto probado de la decisión.','Risultati osservati sulle decisioni misurate: {v} nei loro periodi di misura — osservato ≠ effetto provato della decisione.','Beobachtete Ergebnisse gemessener Entscheidungen: {v} in ihren Messzeiträumen — beobachtet ≠ bewiesene Wirkung.','Waargenomen resultaten van gemeten beslissingen: {v} over hun meetperiodes — waargenomen ≠ bewezen effect van de beslissing.','Resultados observados nas decisões medidas: {v} nos seus períodos de medição — observado ≠ efeito provado da decisão.'],
 nonMes:['Aucun résultat encore mesuré.','No result measured yet.','Aún no hay resultados medidos.','Ancora nessun risultato misurato.','Noch kein Ergebnis gemessen.','Nog geen resultaat gemeten.','Ainda sem resultados medidos.'],
 nonMesEur:['Décisions mesurées sur leur indicateur suivi, pas encore chiffrées en euros.','Decisions measured on their tracked indicator, not yet valued in euros.','Decisiones medidas con su indicador de seguimiento, aún sin cifrar en euros.','Decisioni misurate sul loro indicatore, non ancora quantificate in euro.','Entscheidungen an ihrer verfolgten Kennzahl gemessen, noch nicht in Euro beziffert.','Beslissingen gemeten op hun gevolgde cijfer, nog niet in euro’s uitgedrukt.','Decisões medidas no indicador acompanhado, ainda não quantificadas em euros.'],
 regle:['Estimé et observé ne sont jamais additionnés ; Verdict ne calcule pas de « retour sur abonnement ».','Estimated and observed are never added together; Verdict does not compute a “return on subscription”.','Estimado y observado nunca se suman; Verdict no calcula un «retorno de la suscripción».','Stimato e osservato non vengono mai sommati; Verdict non calcola un «ritorno sull’abbonamento».','Geschätzt und beobachtet werden nie addiert; Verdict berechnet keine „Abo-Rendite“.','Geschat en waargenomen worden nooit opgeteld; Verdict berekent geen „rendement op het abonnement”.','Estimado e observado nunca são somados; o Verdict não calcula um «retorno da subscrição».'],
 vide:['Pas encore assez de données pour un bilan : saisissez vos chiffres ou importez votre FEC.','Not enough data yet for a review: enter your figures or import your FEC.','Aún no hay datos suficientes para un balance: introduzca sus cifras o importe su FEC.','Dati ancora insufficienti per un bilancio: inserite i vostri dati o importate il FEC.','Noch nicht genug Daten für eine Bilanz: Zahlen eingeben oder FEC importieren.','Nog niet genoeg gegevens voor een balans: voer uw cijfers in of importeer uw FEC.','Ainda sem dados suficientes para um balanço: introduza os seus números ou importe o FEC.'],
 demo:['Démonstration : bilan calculé sur les données fictives.','Demo: review computed on fictional data.','Demostración: balance calculado con datos ficticios.','Dimostrazione: bilancio calcolato su dati fittizi.','Demo: Bilanz auf fiktiven Daten.','Demo: balans berekend op fictieve gegevens.','Demonstração: balanço calculado com dados fictícios.']};
function valT(k,v){var i=['fr','en','es','it','de','nl','pt'].indexOf(typeof LOCALE!=='undefined'?LOCALE:'fr');if(i<0)i=0;var a=VAL_TX[k]||[k],s=a[i]||a[0];v=v||{};return String(s).replace(/\{(\w+)\}/g,function(_,x){return v[x]!=null?v[x]:'';});}
