function ntfT(k,v){var i=['fr','en','es','it','de','nl','pt'].indexOf(typeof LOCALE!=='undefined'?LOCALE:'fr');if(i<0)i=0;var a=NTF_TX[k]||[k],s=a[i]||a[0];v=v||{};return String(s).replace(/\{(\w+)\}/g,function(_,x){return v[x]!=null?v[x]:'';});}
var NTF_CATS=['action','mesure','cloture','anomalie','risque','choisi'];
function ntfPrefs(){var p=DB.notifPrefs||{},o={};NTF_CATS.forEach(function(c){o[c]=p[c]!=null?!!p[c]:c!=='choisi';});return o;}
function verdictSignaux(){var out=[],clk=verdictOperationalClock(),jj=function(x){x=String(x||'').slice(0,10);return x?x.split('-').reverse().join('/'):'';};
  try{var J=joursMois(),today=Number(String(clk.civilKey).slice(8)),manq=[],d0=1;/* C301 (V15-098) : depuis le début du suivi */try{var _an=String(clk.civilKey).slice(0,4),_P=DB.performanceYearPlans&&DB.performanceYearPlans[_an],_ts=String(_P&&_P.trackingStart||'');if(_ts.slice(0,7)===String(clk.civilKey).slice(0,7))d0=Math.max(1,Number(_ts.slice(8))||1);}catch(_e){}for(var d=d0;d<today;d++){if(J[d]&&J[d].ca!=null)continue;if(typeof estFerme==='function'&&estFerme(d))continue;manq.push(d);}
    if(manq.length===1)out.push({cat:'action',cle:'action:'+clk.civilKey.slice(0,8)+String(manq[0]).padStart(2,'0'),txt:ntfT('s_action',{d:jj(clk.civilKey.slice(0,8)+String(manq[0]).padStart(2,'0'))})});
    else if(manq.length>1)out.push({cat:'action',cle:'action:manquantes:'+clk.civilKey.slice(0,7)+':'+manq.length,txt:ntfT('s_actions',{n:manq.length,d:jj(clk.civilKey.slice(0,8)+String(manq[0]).padStart(2,'0'))})});}catch(e){}
  try{(decisionsRegistre().decisions||[]).forEach(function(z){if(z.etat==='a-mesurer')out.push({cat:'mesure',cle:'mesure:'+(z.d.id||z.d.trackingId),txt:ntfT('s_mesure',{n:z.d.lib||z.d.id})});});}catch(e){}
  try{var mp=cloMoisPrecedent();if(mp&&!(DB.cloturesMois||{})[mp]&&(DB.histJour||[]).some(function(r){return String(r.date).slice(0,7)===mp;}))out.push({cat:'cloture',cle:'cloture:'+mp,txt:ntfT('s_cloture',{m:typeof prevMoisLabel==='function'?prevMoisLabel(mp):mp})});}catch(e){}
  try{var H=(DB.histJour||[]).filter(function(r){return r&&r.caJ!=null;}).slice().sort(function(a,b){return String(a.date).localeCompare(String(b.date));}),last=H[H.length-1];if(last&&H.length>=5){var prev=H.slice(-9,-1).map(function(r){return Number(r.caJ);}).filter(function(x){return x>0;}).sort(function(a,b){return a-b;}),n=prev.length,med=n%2?prev[(n-1)/2]:(prev[n/2-1]+prev[n/2])/2,c=Number(last.caJ);
    if(n>=4&&med>0&&(c>med*3||c<med*.25))out.push({cat:'anomalie',cle:'anomalie:'+last.date,txt:ntfT(c>med*3?'s_anoHaut':'s_anoBas',{d:jj(last.date),v:eur(c)})});}}catch(e){}
  try{var A=verdictFournisseursAnalyse();((A&&A.sujets)||[]).forEach(function(s){var st=s.variation&&s.variation.statut;if(/erreur|confirm/.test(String(st))&&!/confirmee/.test(String(st)))out.push({cat:'risque',cle:'risque:'+s.id+'|'+s.fournisseur,txt:ntfT('s_risque',{p:s.produit,f:s.fournisseur})});});}catch(e){}
  var P=ntfPrefs();return out.filter(function(x){return P[x.cat];});}
function verdictANotifier(){var S=verdictSignaux(),J=DB.notifJournal=DB.notifJournal||{},today=verdictOperationalClock().civilKey,out=[];
  var deja=Object.keys(J).filter(function(k){return J[k]===today;}).length,reste=Math.max(0,3-deja);S.forEach(function(x){if(out.length>=reste)return;var last=J[x.cle];if(last&&(Date.parse(today)-Date.parse(last))<7*864e5)return;out.push(x);});
  out.forEach(function(x){J[x.cle]=today;});if(out.length){try{save();}catch(e){}}return out;}
function ntfPref(el){DB.notifPrefs=DB.notifPrefs||{};DB.notifPrefs[el.getAttribute('data-cat')]=!!el.checked;try{save();}catch(e){}try{drawAlertes();}catch(e){}}
function verdictNotifHTML(){var S=verdictSignaux(),J=DB.notifJournal||{},today=verdictOperationalClock().civilKey,P=ntfPrefs();
  var h='<div class="card" id="aSignaler"><h3 style="margin:0 0 4px">'+aideEsc(ntfT('titre'))+'</h3><p class="note" style="margin:0 0 6px">'+aideEsc(ntfT('intro'))+'</p>';
  if(!S.length)h+='<p class="note">'+aideEsc(ntfT('aucun'))+'</p>';
  S.forEach(function(x){var neuf=!J[x.cle]||(Date.parse(today)-Date.parse(J[x.cle]))>=7*864e5;h+='<p class="note ntf-l" data-cat="'+x.cat+'" style="margin:3px 0"><b>'+aideEsc(ntfT('c_'+x.cat))+'</b>'+(neuf?' <span class="chip" style="font-size:11px">'+aideEsc(ntfT('nouveau'))+'</span>':'')+' — '+aideEsc(x.txt)+'</p>';});
  h+='<p class="note" style="margin:8px 0 2px;font-weight:600">'+aideEsc(ntfT('prefs'))+'</p><div style="display:flex;flex-wrap:wrap;gap:6px 12px">'+NTF_CATS.map(function(c){return '<label class="note" style="display:flex;gap:4px;align-items:center;min-height:32px"><input type="checkbox" data-cat="'+c+'" onchange="ntfPref(this)"'+(P[c]?' checked':'')+'> '+aideEsc(ntfT('c_'+c))+'</label>';}).join('')+'</div>';
  return h+'</div>';}
function ntfSyncTexte(){var srv=typeof VERDICT_PUBLIC_OPEN!=='undefined'&&!VERDICT_PUBLIC_OPEN;return ntfT('seuils')+' '+ntfT(srv?'syncOK':'syncLocal');}
window.verdictSignaux=verdictSignaux;window.ntfPrefs=ntfPrefs;window.verdictANotifier=verdictANotifier;
