/* ---------- rendu Conseil ---------- */
function prioChip(p){
  if(p>=80) return '<span class="v5chip" style="background:rgba(239,68,68,.12);color:#ef4444"><span class="dt"></span>URGENT \u00b7 priorit\u00e9 '+p+'</span>';
  if(p>=65) return '<span class="v5chip" style="background:rgba(249,115,22,.12);color:#f97316"><span class="dt"></span>IMPORTANT \u00b7 priorit\u00e9 '+p+'</span>';
  if(p>=50) return '<span class="v5chip" style="background:rgba(234,179,8,.12);color:#eab308"><span class="dt"></span>\u00c0 CONSID\u00c9RER \u00b7 priorit\u00e9 '+p+'</span>';
  return '<span class="v5chip" style="background:rgba(34,197,94,.12);color:#22c55e"><span class="dt"></span>SUIVI \u00b7 priorit\u00e9 '+p+'</span>';
}
window.v5fb = function(id,val){
  syncFB();
  FB[id]=FB[id]===val?null:val; saveFB(); drawReco();
};
window.drawReco = function(){
  var el=document.getElementById('recoBody');
  var h1=document.getElementById('recoH1'),sub=document.getElementById('recoSub');
  if(h1)h1.textContent=chrCockpitText('recoTitle');if(sub)sub.textContent=chrCockpitText('recoSubtitle');
  if(!el)return;
  var Rq=v5recos();
  if(!Rq.ready){ el.innerHTML='<div class="warn on">Le Conseil a besoin de vos chiffres \u2014 remplissez d\u2019abord la Saisie.</div>'; return; }
  var C=Rq.conf;
  var confCol = C.pct>=80?'#22c55e':(C.pct>=50?'#eab308':'#ef4444');
  var h='<div class="v5conf"><span>Confiance donn\u00e9es</span><div class="v5confbar"><i style="width:'+C.pct+'%;background:'+confCol+'"></i></div><b style="color:'+confCol+'">'+C.pct+' %</b></div>';
  if(Rq.blocked){
    h+='<div class="warn on"><b>Recommandations en pause \u2014 confiance sous 50 %.</b> Un conseil sur des donn\u00e9es incompl\u00e8tes serait un mauvais conseil. \u00c0 compl\u00e9ter :<br>\u2022 '+C.miss.join('<br>\u2022 ')+'</div>';
    el.innerHTML=h; return;
  }
  if(C.miss.length){
    h+='<p class="note" style="margin-bottom:14px">Am\u00e9liorable : '+C.miss.join(' \u00b7 ')+'</p>';
  }
  Rq.list.forEach(function(r,i){
    var cls = r.veille?'':(i===0?(r.rank<=2&&r.urg>=90?'pR':'p1'):(r.rank<=3?'p2':'p3'));
    var teaser = r.sys && !isPro();
    h+='<div class="v5reco '+cls+'"'+(r.veille?' style="opacity:.55"':'')+'>'+
      '<div class="v5head"><h3>'+(teaser?r.t.replace(/: .*$/,': <span style="color:#585864;font-family:Geist Mono,monospace">\u2022\u2022 \u2022\u2022\u2022 \u20ac/an</span>'):r.t)+'</h3>'+
      (teaser?'<span class="v5chip" style="background:#16161c;color:#585864">\uD83D\uDD12 Verdict Pro</span>':prioChip(r.prio))+'</div>'+
      '<p class="rp">'+(teaser?'Verdict mesure votre food cost r\u00e9el. Verdict Pro le confronte au th\u00e9orique de votre carte et chiffre l\u2019\u00e9cart en euros \u2014 plat par plat.':r.p)+'</p>'+
      (teaser?'<button class="v5btn" style="margin-top:12px;padding:9px 15px;font-size:13px" onclick="v5upgrade()">D\u00e9couvrir Verdict Pro</button>':
        '<div class="why">'+(r.veille?'Mise en veille \u00e0 votre demande \u2014 r\u00e9activable d\u2019un clic.':'Pourquoi celle-ci ? '+r.why)+'</div>'+
        (r.imp>0?'<div class="meta"><span>Urgence '+r.urg+'</span><span>Impact <span class="v5imp">\u2248 '+eur(r.imp)+'/an</span></span><span>Facilit\u00e9 '+r.fac+'</span><span>Confiance '+r.conf+'</span></div>':'')+
        '<div class="v5fb"><button class="'+(FB[r.id]==='ok'?'ok':'')+'" onclick="v5fb(\''+r.id+'\',\'ok\')">\u2713 Appliqu\u00e9e</button>'+
        '<button class="'+(FB[r.id]==='no'?'no':'')+'" onclick="v5fb(\''+r.id+'\',\'no\')">Mettre en veille</button></div>')+
    '</div>';
  });
  h+='<p class="note">Priorit\u00e9 = urgence, impact, facilit\u00e9 et confiance combin\u00e9s \u2014 une seule action en t\u00eate, celle qui p\u00e8se le plus aujourd\u2019hui. Vos r\u00e9ponses (\u00ab Appliqu\u00e9e \u00bb, \u00ab En veille \u00bb) aident Verdict \u00e0 mieux classer les suivantes.</p>';
  el.innerHTML=h;
};
/* ---------- patchs go / refreshAll ---------- */
var _go = window.go;
window.go = function(v){
  /* Le rendu, les verrous et la traduction sont maintenant atomiques dans
     go() : aucun second passage après publication, donc aucun flash tardif. */
  return _go(v);
};
var _refresh = window.refreshAll;
window.refreshAll = function(){
  _refresh();
  if(VIEW==='reco') drawReco();
};
